#!/usr/bin/env python3"""Fix collapsed line 728 in bin/agent/prompts.py."""import sysfrom pathlib import Pathfilepath = Path("bin/agent/prompts.py")content = filepath.read_text(encoding="utf-8")lines = content.split("\n")# Line 728 (1-indexed) = index 727target_idx = 727line = lines[target_idx]print(f"Line {target_idx+1} length: {len(line)}", flush=True)print(f"Starts with: {line[:80]}", flush=True)if "def _serialize_element" not in line:    print("ERROR: Line 728 does not contain _serialize_element", flush=True)    sys.exit(1)# This single line contains: _serialize_element, _write_prompts_xml, two def _indent headers,# and the start of _indent body (spaces = ...)# Lines 729-738 (index 728-737) contain the rest of _indent body# Line 739 (index 738) is empty, line 740 (index 739) is empty# Line 741 (index 740) is def _prompt_node# Find where _indent body endsend_idx = target_idxfor j in range(target_idx + 1, min(target_idx + 20, len(lines))):    if "def _prompt_node" in lines[j]:        end_idx = j - 1        # Remove trailing empty lines        while end_idx > target_idx and lines[end_idx].strip() == "":            end_idx -= 1        breakprint(f"Replacing lines {target_idx+1} through {end_idx+1}", flush=True)new_code = [    'def _serialize_element(element: ET.Element, level: int = 0) -> str:',    '    """Serialize an element to XML, using CDATA for value elements."""',    '    indent = "  " * level',    '    parts: list[str] = []',    '    attrs = "".join(f\' {k}="{v}\' for k, v in element.attrib.items())',    '    if len(element) == 0 and (element.text is None or not element.text.strip()):',    '        if element.tag:',    '            parts.append(f"{indent}<{element.tag}{attrs} />")',    '        return "".join(parts)',    '    parts.append(f"{indent}<{element.tag}{attrs}>")',    '    if element.tag == "value" and element.text is not None:',    '        cdata = element.text.replace("]]>", "]]]]><![CDATA[>")',    '        parts.append(f"<![CDATA[{cdata}]]>")',    '    elif element.text:',    '        parts.append(element.text)',    '    for child in element:',    '        parts.append("\\n")',    '        parts.append(_serialize_element(child, level + 1))',    '    if len(element) > 0:',    '        parts.append(f"\\n{indent}")',    '    parts.append(f"</{element.tag}>")',    '    return "".join(parts)',    '',    'def _write_prompts_xml(tree: ET.ElementTree, path: Path) -> None:',    '    """Write the prompts XML with CDATA sections for all value elements."""',    '    root = tree.getroot()',    "    xml_str = '<?xml version=\"1.0\" encoding=\"utf-8\"?>\\n'",    '    xml_str += _serialize_element(root)',    '    xml_str += "\\n"',    '    path.write_text(xml_str, encoding="utf-8")',    '',    '',]new_lines = lines[:target_idx] + new_code + lines[end_idx + 1:]filepath.write_text("\n".join(new_lines), encoding="utf-8")print("File written successfully", flush=True)